-- November legacy Mon/Tue slots were autogenerated every 30 minutes.
-- Keep Oct 19/20/26/27 unchanged. Future Mon/Tue open only by explicit admin date toggle.
CREATE TABLE IF NOT EXISTS public.regular_weekday_open_dates (
  date_key date PRIMARY KEY,
  opened_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT regular_weekday_open_dates_only_mon_tue
    CHECK (extract(isodow from date_key) in (1, 2))
);
ALTER TABLE public.regular_weekday_open_dates ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.regular_weekday_open_dates FROM anon, authenticated;
GRANT ALL ON TABLE public.regular_weekday_open_dates TO service_role;

CREATE OR REPLACE FUNCTION public.munjang_set_monday_tuesday_open(
  p_date_key text,
  p_is_open boolean
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_date date;
  v_start timestamptz;
  v_end timestamptz;
  v_time text;
  v_slot_start timestamptz;
  v_slot_end timestamptz;
  v_count int := 0;
BEGIN
  IF p_date_key IS NULL OR p_date_key !~ '^\\d{4}-\\d{2}-\\d{2}$' THEN
    RAISE EXCEPTION '올바른 날짜를 선택해 주세요.';
  END IF;
  v_date := p_date_key::date;
  IF v_date::text <> p_date_key OR v_date < date '2026-10-01'
    OR extract(isodow from v_date) NOT IN (1, 2) THEN
    RAISE EXCEPTION '2026년 10월 이후 월요일 또는 화요일을 선택해 주세요.';
  END IF;
  IF v_date IN (date '2026-10-19', date '2026-10-20', date '2026-10-26', date '2026-10-27') THEN
    RAISE EXCEPTION '10월에 직접 개방한 보호 일정은 변경할 수 없습니다.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext(p_date_key), 291017);
  v_start := (v_date::timestamp AT TIME ZONE 'Asia/Seoul');
  v_end := ((v_date + 1)::timestamp AT TIME ZONE 'Asia/Seoul');

  -- Retain rows and all existing bookings; only their bookability is toggled.
  UPDATE public.available_slots
  SET is_open = false
  WHERE start_at >= v_start AND start_at < v_end;

  IF p_is_open THEN
    FOR v_time IN SELECT unnest(ARRAY['14:00','15:40','17:00','19:00','20:40']) LOOP
      v_slot_start := ((v_date::text || ' ' || v_time)::timestamp AT TIME ZONE 'Asia/Seoul');
      v_slot_end := v_slot_start + CASE WHEN v_time = '15:40'
        THEN interval '45 minutes' ELSE interval '90 minutes' END;
      INSERT INTO public.available_slots(start_at, end_at, is_open)
      VALUES(v_slot_start, v_slot_end, true)
      ON CONFLICT (start_at) DO UPDATE
      SET is_open = true,
          end_at = CASE WHEN EXISTS(
            SELECT 1 FROM public.regular_bookings b
            WHERE b.slot_id = available_slots.id
          ) THEN available_slots.end_at ELSE excluded.end_at END;
      v_count := v_count + 1;
    END LOOP;
    INSERT INTO public.regular_weekday_open_dates (date_key)
    VALUES (v_date)
    ON CONFLICT (date_key) DO UPDATE SET opened_at = now();
  ELSE
    DELETE FROM public.regular_weekday_open_dates WHERE date_key = v_date;
  END IF;

  RETURN jsonb_build_object('ok', true, 'date', p_date_key, 'is_open', p_is_open, 'count', v_count);
END;
$$;
REVOKE ALL ON FUNCTION public.munjang_set_monday_tuesday_open(text, boolean)
  FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.munjang_set_monday_tuesday_open(text, boolean)
  TO service_role;

-- Close legacy Nov Mon/Tue 30-minute entries by default. Preserve booked rows.
-- No regular booking exists on these dates at migration time.
UPDATE public.available_slots AS s
SET is_open = false
WHERE s.start_at >= timestamptz '2026-11-01 00:00:00+09'
  AND s.start_at < timestamptz '2026-12-01 00:00:00+09'
  AND extract(isodow from s.start_at AT TIME ZONE 'Asia/Seoul') IN (1,2)
  AND NOT EXISTS(
    SELECT 1 FROM public.regular_bookings b
    WHERE b.slot_id = s.id AND b.status IN ('booked','change_request','cancel_request')
  );
